input.command:
gh api graphql -f query='
{
  search(query: "repo:cli/cli is:pr created:2024-04-01..2024-06-30", type: ISSUE, first: 1) {
    issueCount
  }
}' 2>&1

gh api graphql -f query='
{
  search(query: "repo:cli/cli is:pr created:2024-04-01..2024-06-30", type: ISSUE, first: 100) {
    nodes {
      ... on PullRequest {
        number
        createdAt
        mergedAt
        closedAt
        state
        changedFiles
        author { login }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}' 2>&1

gh api graphql -f query='
{
  search(query: "repo:cli/cli is:pr created:2024-04-01..2024-06-30", type: ISSUE, first: 100, after: "Y3Vyc29yOjEwMA==") {
    nodes {
      ... on PullRequest {
        number
        createdAt
        mergedAt
        closedAt
        state
        changedFiles
        author { login }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}' 2>&1
